export function parseNamedRegistrySpecifierToRegistryPackageSpec (
  rawSpecifier: string,
  knownRegistryNames: ReadonlySet<string>,
  packageAlias: string | undefined,
  defaultTag: string
): NamedRegistryPackageSpec | null {
  const colonIndex = rawSpecifier.indexOf(':')
  if (colonIndex === -1) return null
  const registryName = rawSpecifier.slice(0, colonIndex)
  // The 'github:' git shorthand and other reserved prefixes belong to other resolvers.
  if (RESERVED_SPECIFIER_PREFIXES.has(registryName)) return null
  if (!knownRegistryNames.has(registryName)) return null

  const body = rawSpecifier.slice(colonIndex + 1)

  let name: string
  let versionSelector: string | undefined
  if (body[0] === '@') {
    // syntax: <alias>:@<scope>/<name>[@<version_selector>]
    const index = body.lastIndexOf('@')
    if (index === 0) {
      name = body
      versionSelector = undefined
