    const selector = getVersionSelectorType(body)
    if (selector != null) {
      // syntax: <alias>:<version_selector> — the package name must come from the alias.
      if (!packageAlias) return null
      name = packageAlias
      versionSelector = body
    } else {
      // syntax: <alias>:<name>[@<version_selector>]
      const index = body.lastIndexOf('@')
      if (index < 1) {
        name = body
        versionSelector = undefined
      } else {
        name = body.slice(0, index)
        versionSelector = body.slice(index + 1)
      }
    }
  }

  const selector = getVersionSelectorType(versionSelector ?? defaultTag)
  if (selector == null) return null

  return {
    fetchSpec: selector.normalized,
    name,
    type: selector.type,
    registryName,
  }
}

function isValidScopedPackageName (name: string): boolean {
  if (name[0] !== '@') return name.length > 0
  const slashIndex = name.indexOf('/')
  if (slashIndex === -1) return false
  const scope = name.slice(1, slashIndex)
  const pkgName = name.slice(slashIndex + 1)
  return scope.length > 0 && pkgName.length > 0
}
